import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Techniques & Familiarity","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/characters/techniques.md","filePath":"en/guide/characters/techniques.md"}'),s={name:"en/guide/characters/techniques.md"};function n(l,e,o,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="techniques-familiarity" tabindex="-1">Techniques &amp; Familiarity <a class="header-anchor" href="#techniques-familiarity" aria-label="Permalink to &quot;Techniques &amp; Familiarity&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Availability not established.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li><a href="/Syrolands-Public/en/guide/characters/skills.html">Skill</a> supports execution; a learned <a href="/Syrolands-Public/en/guide/glossary.html#technique">Technique</a> opens a particular possibility.</li><li><a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity</a> means practiced fluency, separate from knowledge and preparation.</li><li>Teachers, discovery and reputation support specialization without permanent classes.</li></ul><p><span id="techniques-specializations"></span><span id="skill-is-capability-techniques-are-knowledge"></span><span id="learning-through-the-world"></span><span id="more-to-discover-after-100"></span><span id="practice-and-ready-options"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Player meaning</th></tr></thead><tbody><tr><td>Learn</td><td>Find procedures and schools through teachers, books, exploration and suitable challenges.</td></tr><tr><td>Practice</td><td>Improve fluency with known actions; skill alone does not grant every technique.</td></tr><tr><td>Prepare</td><td>Choose ready combat options or magical patterns from what you know. Preparation does not teach them.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Weapon special moves and Skill Masteries depend on the UO era.</td><td>Learn <a href="/Syrolands-Public/en/guide/combat/special-attacks.html">SAs</a> and other techniques through the world, then practice and prepare them.</td></tr><tr><td>Skill investment helps define a character build.</td><td>Learned knowledge, practice and reputation also distinguish equally skilled characters.</td></tr></tbody></table><p>UO rules vary by era and shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/skill-masteries/" target="_blank" rel="noreferrer">Official UO: Skill Masteries</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A skilled carpenter might still seek a Bowmaking teacher. Learning the process opens a path toward becoming a renowned bowyer; it does not automatically supply perfect execution.</p><h2 id="progression-trade-offs" tabindex="-1">Progression / trade-offs <a class="header-anchor" href="#progression-trade-offs" aria-label="Permalink to &quot;Progression / trade-offs&quot;">​</a></h2><p>Techniques are not all mutually exclusive. Specialization comes from investment, learning and practice. Teaching rights, respecialization and broader knowledge-transfer rules remain open.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity and practice</a> · <a href="/Syrolands-Public/en/guide/characters/skills.html">Skills</a> · <a href="/Syrolands-Public/en/guide/combat/special-attacks.html">Special Attacks</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p>Read the <a href="/Syrolands-Public/en/game-design/characters/techniques-and-specialization.html">Techniques &amp; Familiarity</a> design specification.</p>',18)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
